<script setup lang="ts">
import {nextTick,ref,watch} from 'vue'
type Facility={id:string;name:string;address:string;riskScore:number|null;rainfallMm:number|null;remainingCount?:number|null;pendingReviewCount?:number|null}
const props=defineProps<{facility:Facility|null;cluster:Facility[];state:string;control:string;observed:string;loading:boolean;error:string;weather?:{temperature?:number|null;condition?:string};weatherLoading:boolean;weatherError:string;riskPoints:string;canControl:boolean}>()
const expanded=defineModel<boolean>('expanded',{default:true}),panel=ref<HTMLElement>()
defineEmits<{select:[id:string];clear:[];control:[index:number];cctv:[]}>()
watch(()=>props.facility?.id,async id=>{if(id){await nextTick();panel.value?.focus({preventScroll:true})}})
</script>
<template><section ref="panel" class="manager-map-panel" aria-label="선택 시설" tabindex="-1"><header><h2>{{cluster.length&&!facility?'묶음 시설 '+cluster.length+'곳':'선택 시설'}}</h2><button type="button" :aria-expanded="expanded" aria-controls="manager-map-panel-body" @click="expanded=!expanded">{{expanded?'상세 접기 ▴':'상세 펼치기 ▾'}}</button></header><div v-if="facility" class="manager-facility-heading"><strong>{{facility.name}}</strong><p>{{facility.address||'주소 미제공'}}</p><div><span class="manager-state" :class="state==='통제'||state==='위험'?'danger':state==='경고'?'warning':'safe'">{{state==='정상'?'안전':state==='경고'?'주의':state}}</span><span>{{control}}</span><button type="button" aria-label="시설 선택 해제" @click="$emit('clear')">×</button></div></div><div v-show="expanded" id="manager-map-panel-body" class="manager-panel-body"><template v-if="facility"><p v-if="loading" role="status">최신 상태 조회 중…</p><p v-if="error" role="alert">{{error}}</p><div class="manager-risk"><strong>{{facility.riskScore===null?'—':facility.riskScore.toFixed(1)}}<small>점</small></strong><span>위험 점수</span></div><div class="manager-gauge"><b :style="{width:Math.max(0,Math.min(100,facility.riskScore||0))+'%'}"></b></div><dl><dt>강우량</dt><dd>{{facility.rainfallMm??'—'}} mm</dd><dt>잔류 차량</dt><dd>{{facility.remainingCount??'—'}}대</dd><dt>판별 대기</dt><dd>{{facility.pendingReviewCount??'—'}}건</dd><dt>관측 시각</dt><dd>{{observed}}</dd></dl><div class="manager-weather"><b>시설 위치 날씨</b><p v-if="weatherLoading">날씨 조회 중…</p><p v-else-if="weatherError">{{weatherError}}</p><p v-else>{{weather?.condition||'기상 상태 미제공'}} · {{weather?.temperature??'—'}}°C</p></div><details><summary>관측 기록</summary><svg v-if="riskPoints" viewBox="0 0 300 130" role="img" aria-label="선택 시설 위험도 관측 기록"><path d="M20 10V110H280" fill="none" stroke="#c9ced6"/><polyline :points="riskPoints" fill="none" stroke="#225f9b" stroke-width="3"/></svg><p v-else>조회된 관측 기록이 없습니다.</p></details><div v-if="canControl" class="manager-control-actions"><button type="button" :disabled="loading||!!error||control==='통제 중'" @click="$emit('control',0)">통제</button><button type="button" :disabled="loading||!!error||control!=='통제 중'" @click="$emit('control',1)">통제 해제</button></div><button type="button" @click="$emit('cctv')">주변 CCTV 보기</button><RouterLink :to="'/fac-detail?id='+facility.id">시설 상세 →</RouterLink></template><ul v-else-if="cluster.length" class="manager-cluster-options"><li v-for="row in cluster" :key="row.id"><button type="button" @click="$emit('select',row.id)">{{row.name}} <span aria-hidden="true">›</span></button></li></ul><p v-else class="manager-selection-hint">지도에서 마커를 누르면 해당 시설의 상세 정보가 표시됩니다.</p></div></section></template>
<style scoped>
